package ai.decisionos.aside;
import android.os.*;import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class BlackboardFilesChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();try{
 String id="";try(GoalStore s=new GoalStore(i.getTargetContext())){for(JSONObject g:s.goals())if(!GoalStore.fixture(g)&&g.optString("character").equals("grades")){id=g.optString("id");break;}}String url=i.scenario.getString("bbUrl","");if(!BlackboardDownloads.allowed(url))throw new Exception("Observed course URL required");
 GoalAgentActivity a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final BlackboardTools[] t={null};i.runOnMainSync(()->{t[0]=new BlackboardTools(a.chat);t[0].show(url,false);});Thread.sleep(15000);i.runOnMainSync(()->t[0].run("materials",null,true));Thread.sleep(10000);i.check(t[0].candidates.length()>0,"real course materials extracted");Set<String> before=new HashSet<>();try(CampusFlowStore s=new CampusFlowStore(a)){for(JSONObject f:s.list("bb_downloads"))before.add(f.optString("id"));}i.runOnMainSync(()->BlackboardDownloads.start(a,new JSONArray().put(t[0].candidates.optJSONObject(0)),null));JSONObject downloaded=null;for(int n=0;n<45;n++){try(CampusFlowStore s=new CampusFlowStore(a)){for(JSONObject f:s.list("bb_downloads"))if(!before.contains(f.optString("id"))&&!f.optString("state").equals("queued")){downloaded=f;break;}}if(downloaded!=null)break;Thread.sleep(1000);}i.check(downloaded!=null&&downloaded.optString("state").equals("downloaded"),"native download complete: "+(downloaded==null?"timeout":downloaded.optString("reason")));
 File file=new File(new File(a.getFilesDir(),"documents"),downloaded.getString("filename"));i.check(file.length()==downloaded.getLong("bytes")&&file.length()>0,"stored bytes match");java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");byte[] first=new byte[5];try(InputStream in=new FileInputStream(file)){i.check(in.read(first)==5&&new String(first,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"),"actual PDF header");}try(InputStream in=new FileInputStream(file)){byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1)digest.update(buf,0,n);}StringBuilder sha=new StringBuilder();for(byte b:digest.digest())sha.append(String.format(java.util.Locale.ROOT,"%02x",b&255));i.check(sha.toString().equals(downloaded.getString("sha256")),"actual saved file SHA256");
 i.runOnMainSync(()->t[0].run("notices",null,true));Thread.sleep(7000);int notices=0;try(CampusFlowStore s=new CampusFlowStore(a)){for(JSONObject r:s.list("observations"))if(r.optString("id").startsWith("bb-notice:"))notices++;}i.check(notices>0,"actual announcements persisted");
 try(FileOutputStream f=new FileOutputStream(new File(a.getCacheDir(),"blackboard-files.png"))){i.getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}JSONObject evidence=new JSONObject().put("checks",i.checks).put("materials",t[0].candidates.length()).put("notices",notices).put("bytes",file.length()).put("sha256",sha.toString());try(FileOutputStream f=new FileOutputStream(new File(a.getCacheDir(),"blackboard-files-proof.json"))){f.write(evidence.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}Thread.sleep(30000);out.putString("stream","PASS "+i.checks+" actual course material/native download/PDF hash/announcement checks\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
